CREATE TEMPORARY VIEW traffic_data_raw_${grass_region_without_quote} AS
SELECT
     if(operation='order','order','others') as operation
    ,local_hour
    ,is_item_card
    ,shop_id
    ,item_id
    ,model_id
    ,user_id
    ,if(is_ads,'true','false') as is_ads
    ,if(source1_is_ads,'true','false') as source1_is_ads
    ,if(source2_is_ads,'true','false') as source2_is_ads
    ,feature_detail
    ,source1_feature_detail
    ,source2_feature_detail
    ,feature_group
    ,reporting_business_line
    ,reporting_module
    ,reporting_object
    ,source1_feature_group
    ,source1_reporting_business_line
    ,source1_reporting_module
    ,source1_reporting_object
    ,source2_feature_group
    ,source2_reporting_business_line
    ,source2_reporting_module
    ,source2_reporting_object
    ,sum(imp_cnt)   as imp_cnt
    ,sum(click_cnt) as click_cnt
    ,sum(order_cnt)      as order_cnt
    ,sum(gmv)            as gmv
    ,sum(gmv_local)      as gmv_local
    ,sum(pc2_gmv)        as pc2_gmv
FROM srdi_mart.dwm_sr_data_warehouse_tc_ab_all_cards
WHERE grass_region IN (${grass_region}) AND local_date = ${local_date}
and operation in ('order')
group by
     if(operation='order','order','others')
    ,local_hour
    ,is_item_card
    ,shop_id
    ,item_id
    ,model_id
    ,user_id
    ,is_ads
    ,source1_is_ads
    ,source2_is_ads
    ,feature_detail
    ,source1_feature_detail
    ,source2_feature_detail
    ,feature_group
    ,reporting_business_line
    ,reporting_module
    ,reporting_object
    ,source1_feature_group
    ,source1_reporting_business_line
    ,source1_reporting_module
    ,source1_reporting_object
    ,source2_feature_group
    ,source2_reporting_business_line
    ,source2_reporting_module
    ,source2_reporting_object
;

