--CACHE TABLE  every_scene_data_raw_step1_${grass_region_without_quote} AS (
CREATE TEMPORARY VIEW  every_scene_data_raw_step1_${grass_region_without_quote} AS (
select
     operation
    ,is_item_card
    ,user_id
    ,is_ads
    ,source1_is_ads
    ,source2_is_ads

    ,shop_id
    ,item_id
    ,model_id

    ,case
       when reporting_business_line in ('Search') and reporting_module in ('Global Search') then 'Search'
       when reporting_module in ('Daily Discover') then 'Daily Discover'
       when reporting_object in ('you may also like') then 'You May Also Like'
       when reporting_business_line in ('Rcmd') and reporting_module in ('User Scenario') and reporting_object in ('post purchase') then 'Post Purchase'
       when reporting_business_line in ('Shop(Non Rcmd)') or (reporting_business_line = 'Rcmd' and reporting_module = 'Private Domin') then 'Shop'
       else '' -- 任何非归因数据都需要有场景
     end as mapping_general
    ,case
       when source1_reporting_business_line in ('Search') and source1_reporting_module in ('Global Search') then 'Search'
       when source1_reporting_module in ('Daily Discover') then 'Daily Discover'
       when source1_reporting_object in ('you may also like') then 'You May Also Like'
       when source1_reporting_business_line in ('Rcmd') and source1_reporting_module in ('User Scenario') and source1_reporting_object in ('post purchase') then 'Post Purchase'
       else ''
     end as source1_mapping_general
    ,case
       when source2_reporting_business_line in ('Search') and source2_reporting_module in ('Global Search') then 'Search'
       when source2_reporting_module in ('Daily Discover') then 'Daily Discover'
       when source2_reporting_object in ('you may also like') then 'You May Also Like'
       when source2_reporting_business_line in ('Rcmd') and source2_reporting_module in ('User Scenario') and source2_reporting_object in ('post purchase') then 'Post Purchase'
       else ''
     end as source2_mapping_general

    ,imp_cnt
    ,click_cnt
    ,order_cnt
    ,gmv
    ,gmv_local
    ,pc2_gmv
    ,local_hour
from traffic_data_raw_${grass_region_without_quote}
where ( -- to reduce data size
       (reporting_business_line in ('Search') and reporting_module in ('Global Search'))
       or
       (reporting_module in ('Daily Discover'))
       or
       (reporting_object in ('you may also like'))
       or
       (reporting_business_line in ('Rcmd') and reporting_module in ('User Scenario') and reporting_object in ('post purchase'))
       or
       (reporting_business_line in ('Shop(Non Rcmd)') or (reporting_business_line = 'Rcmd' and reporting_module = 'Private Domin'))
    or
       (source1_reporting_business_line in ('Search') and source1_reporting_module in ('Global Search'))
       or
       (source1_reporting_module in ('Daily Discover'))
       or
       (source1_reporting_object in ('you may also like'))
       or
       (source1_reporting_business_line in ('Rcmd') and source1_reporting_module in ('User Scenario') and source1_reporting_object in ('post purchase'))
    or
       (source2_reporting_business_line in ('Search') and source2_reporting_module in ('Global Search'))
       or
       (source2_reporting_module in ('Daily Discover'))
       or
       (source2_reporting_object in ('you may also like'))
       or
       (source2_reporting_business_line in ('Rcmd') and source2_reporting_module in ('User Scenario') and source2_reporting_object in ('post purchase'))
   )
)
;

