CREATE TEMPORARY VIEW every_scene_data_raw_step2_${grass_region_without_quote} AS
select -- include order log item_card and imp&click all_card
     is_item_card
    ,user_id
    ,is_ads
    ,mapping_general

    ,shop_id
    ,item_id
    ,model_id

    ,imp_cnt
    ,click_cnt
    ,order_cnt
    ,gmv
    ,gmv_local
    ,pc2_gmv
    ,local_hour
from every_scene_data_raw_step1_${grass_region_without_quote}
where ( -- only SR scene has non-item-cards for imp/click ,for order will add live
mapping_general in ('Search','Daily Discover','You May Also Like','Post Purchase')
or -- shop and other only has item-card, this is for removing dirty data
mapping_general in ('Shop') and is_item_card='true'
)
union all
select  'false' as is_item_card	-- copy order log from source1
        ,user_id
        ,source1_is_ads as is_ads
        ,source1_mapping_general as mapping_general

        ,shop_id
        ,item_id
        ,model_id

        ,imp_cnt
        ,click_cnt
        ,order_cnt
        ,gmv
        ,gmv_local
        ,pc2_gmv
        ,local_hour
from    every_scene_data_raw_step1_${grass_region_without_quote}
where   source1_mapping_general in ('Search', 'Daily Discover', 'You May Also Like', 'Post Purchase')
  and   operation = 'order'
  and   source1_mapping_general != mapping_general	--to guarantee order not copy double,and so the only non_item_card is not right,but no body only need this
union all
select  'false' as is_item_card	-- copy order log from source2
        ,user_id
        ,source2_is_ads as is_ads
        ,source2_mapping_general as mapping_general

        ,shop_id
        ,item_id
        ,model_id

        ,imp_cnt
        ,click_cnt
        ,order_cnt
        ,gmv
        ,gmv_local
        ,pc2_gmv
        ,local_hour
from    every_scene_data_raw_step1_${grass_region_without_quote}
where   source2_mapping_general in ('Search', 'Daily Discover', 'You May Also Like', 'Post Purchase')
  and   operation = 'order'
  and   source2_mapping_general != mapping_general
  and   source2_mapping_general != source1_mapping_general	--to guarantee order not copy double
;
--sql_divide_splitter--

